const order = $input.first().json.body;

const customerName = order.billing_address?.first_name || order.customer?.first_name || 'Pelanggan';
const orderId = order.order_number || order.id;
const total = new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', minimumFractionDigits: 0 }).format(order.total_price);
const items = order.line_items?.map(item => `• ${item.name} x${item.quantity}`).join('\n') || '';
const phone = order.billing_address?.phone || order.customer?.phone || '';

// Format Indonesian phone number for WhatsApp API
const cleanPhone = phone.replace(/[^0-9]/g, '');
const waPhone = cleanPhone.startsWith('0') ? '62' + cleanPhone.slice(1) : cleanPhone.startsWith('62') ? cleanPhone : '62' + cleanPhone;

return [{
  json: {
    customerName,
    orderId,
    total,
    items,
    phone: waPhone,
    email: order.customer?.email || '',
    message: `Halo ${customerName}! 🐾\n\nPesanan Pawmeals kamu sudah dikonfirmasi!\n\n📦 Order #${orderId}\n${items}\n\n💰 Total: ${total}\n\nTim Pawmeals akan segera memproses pesananmu. Estimasi pengiriman 1-3 hari kerja.\n\nAda pertanyaan? Balas pesan ini atau hubungi kami di pawmeals.id 🐶🐱`
  }
}];
